/* Test stand-in for the external CMAC256 function.
 *
 * NOT AES-CMAC and NOT secure: a CBC-MAC over a cheap keyed mixing
 * function, with 0x80 padding so messages of different lengths give
 * different tags. Deterministic, and every tag octet depends on every key
 * and message octet, which is all CCSDSSDLSEncryptor's tests need.
 *
 * set_cmac_status selects the status the next calls report, so test_env can
 * exercise the encryptor's crypto-backend-failed path.
 */
#include "cmac256_mock.h"

#include <stdint.h>
#include <string.h>

static asn1SccCrypto_Status g_status = Crypto_Status_ok;

static void mix(uint8_t s[16], const uint8_t key[32])
{
   for (unsigned r = 0; r < 4; r++) {
      for (unsigned i = 0; i < 16; i++) {
         uint8_t v = (uint8_t)(s[i] ^ key[i + 16 * (r & 1)]);
         v = (uint8_t)((v << 5) | (v >> 3));
         s[i] = (uint8_t)(v + s[(i + 15) % 16] + r);
      }
   }
}

void cmac256_mock_startup(void)
{
}

void cmac256_mock_PI_cmac256
      (const asn1SccAES256_Key *IN_key,
       const asn1SccCMAC_Message *IN_message,
       asn1SccCMAC_Tag *OUT_tag,
       asn1SccCrypto_Status *OUT_status)

{
   *OUT_status = g_status;
   memset(OUT_tag->arr, 0, sizeof(OUT_tag->arr));
   if (g_status != Crypto_Status_ok) {
      return;
   }

   const size_t len = (size_t)IN_message->nCount;
   size_t i = 0;
   for (;;) {
      uint8_t block[16] = { 0 };
      size_t n = (len - i < 16) ? len - i : 16;
      memcpy(block, IN_message->arr + i, n);
      i += n;
      if (n < 16) {
         block[n] = 0x80; /* final, padded block */
      }
      for (unsigned j = 0; j < 16; j++) {
         OUT_tag->arr[j] ^= block[j];
      }
      mix(OUT_tag->arr, IN_key->arr);
      if (n < 16) {
         break;
      }
   }
}

void cmac256_mock_PI_set_cmac_status
      (const asn1SccCrypto_Status *IN_status)

{
   g_status = *IN_status;
}
